# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL VE BEŞERÎ ÇEVRENİN NÜFUS DAĞILIŞINA ETKİSİ (SB.6.2.2)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yoğun Nüfuslu Alanlar ve Nedenleri</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#14532d">• Çatalca-Kocaeli (İstanbul-Kocaeli): Sanayi,</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#14532d">ticaret, ulaşım kavşağı ve ılıman iklim.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11" fill="#14532d">• Kıyı Ege (İzmir) ve Çukurova (Adana):</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#14532d">Verimli delta ovaları, tarım, liman ve sanayi.</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11" fill="#14532d">• Antalya Körfezi: İklim ve kıyı turizmi.</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">• Doğu Karadeniz Kıyısı: Ilıman kıyı şeridi.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Seyrek Nüfuslu Alanlar ve Nedenleri</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#7f1d1d">• Tuz Gölü ve Çevresi: Yetersiz yağış ve</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#7f1d1d">şiddetli kuraklık (Doğal faktör: İklim/Su).</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11" fill="#7f1d1d">• Hakkâri ve Doğu Anadolu Yüksekleri:</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#7f1d1d">Engebeli yer şekilleri ve sert kış şartları.</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" fill="#7f1d1d">• Teke ve Taşeli Platoları: Karstik arazi.</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">• Menteşe ve Yıldız Dağları: Dağlık yapı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL ÇEVRENİN YERLEŞME DOKUSU VE KONUT TİPLERİNE ETKİSİ</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kırsal Yerleşme Dokuları</text>\n  <text x="180" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1. Dağınık Yerleşme (Karadeniz):</text>\n  <text x="180" y="126" text-anchor="middle" font-size="11" fill="#334155">Arazi dağlık ve engebeli, su kaynakları bol,</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" fill="#334155">tarım alanları parçalı → Evler birbirinden uzak.</text>\n  <text x="180" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2. Toplu Yerleşme (İç ve Güneydoğu Anadolu):</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11" fill="#334155">Arazi düz ve sade, su kaynakları kısıtlı →</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#334155">Evler su kaynağının etrafında bir arada.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Doğal Malzemeye Göre Konut Tipleri</text>\n  <text x="520" y="110" text-anchor="middle" font-size="12" fill="#713f12">• Karadeniz Bölgesi: Yağış ve orman bol</text>\n  <text x="520" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">→ Ahşap Evler</text>\n  <text x="520" y="154" text-anchor="middle" font-size="12" fill="#713f12">• İç ve Güneydoğu Anadolu: Kurak iklim, toprak</text>\n  <text x="520" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">→ Kerpiç (Toprak) Evler</text>\n  <text x="520" y="198" text-anchor="middle" font-size="12" fill="#713f12">• Akdeniz ve Kapadokya (Nevşehir-Mardin):</text>\n  <text x="520" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">→ Taş Evler (Kalker ve Volkanik Tüf)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EKONOMİK FAALİYETLER VE SÜRDÜRÜLEBİLİR ÇEVRE ETKİLEŞİMİ</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">İklim ve Yer Şekillerinin Ekonomiye Etkisi</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#164e63">• Akdeniz İklimi: Kış ılıklığı → Seracılık,</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#164e63">turunçgil, zeytin; yaz güneşlenmesi → Kıyı turizmi.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11" fill="#164e63">• Karadeniz İklimi: Her mevsim yağış → Çay,</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#164e63">fındık, ormancılık ve yayla turizmi.</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11" fill="#164e63">• Erzurum-Kars: Yaz yağışlarıyla gür çayırlar</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">→ Büyükbaş mera hayvancılığı ve kış turizmi.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Beşerî Müdahale ve Sürdürülebilirlik</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#7c2d12">• Ulaşım: Dağlık alanlarda tüneller (Ovit, Zigana),</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#7c2d12">viyadükler ve boğaz köprüleri inşa edilir.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11" fill="#7c2d12">• Tarım ve Enerji: Kurak ovalar için barajlar ve</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#7c2d12">sulama kanalları (GAP, Konya Ovası Projesi).</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">• Sürdürülebilirlik: Doğal dengeyi bozmadan,</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" fill="#7c2d12">verimli tarım arazilerini imara açmadan gelişim.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
